SELECT job_title, CASE WHEN salary >= 127000 THEN 'high' WHEN salary >= 50000 THEN 'mid' ELSE 'low' END AS salary_bucket, ROUND((100 * SUM(CASE WHEN job_title = 'Director' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_director, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values FROM employees WHERE LENGTH(full_name) < 13 AND dept_id IN (5, 6) GROUP BY job_title, CASE WHEN salary >= 127000 THEN 'high' WHEN salary >= 50000 THEN 'mid' ELSE 'low' END HAVING pct_l3 < 35
